import { GripHorizontal, GripVertical } from 'lucide-react';
import {
  Children,
  createContext,
  isValidElement,
  useContext,
  useId,
  useRef,
  useState,
  type HTMLAttributes,
  type KeyboardEvent,
  type PointerEvent,
  type ReactElement,
  type Ref,
} from 'react';
import { cn } from '../../utils/cn';
import {
  defaultSizes,
  isCollapsed,
  loadSizes,
  movePair,
  saveSizes,
  setPair,
  clamp,
  type PanelConstraints,
} from './resizable-layout';
import { useI18n } from '../../i18n/I18nProvider';
import { resizableVariants } from './resizable.variants';

type Direction = 'horizontal' | 'vertical';

interface GroupContextValue {
  direction: Direction;
  panels: PanelConstraints[];
  sizes: number[];
  restore: Record<string, number>;
  /** Applies new sizes; `persist` also writes them to localStorage (autoSaveId). */
  update: (sizes: number[], options?: { persist?: boolean; restore?: Record<string, number> }) => void;
}

const GroupContext = createContext<GroupContextValue | null>(null);
/** Index of the panel (for a panel) or of the panel before it (for a handle). */
const SlotContext = createContext<number>(-1);

function useGroup(part: string) {
  const ctx = useContext(GroupContext);
  if (!ctx) throw new Error(`${part} must be a direct child of <ResizablePanelGroup>.`);
  return ctx;
}

type DivProps = Omit<HTMLAttributes<HTMLDivElement>, 'className'> & { className?: string; ref?: Ref<HTMLDivElement> };

export interface ResizablePanelGroupProps extends DivProps {
  /** `horizontal` lays panels out side by side (vertical handles); `vertical` stacks them. */
  direction?: Direction;
  /** Remembers the layout in localStorage under this key (ignored when storage is unavailable). */
  autoSaveId?: string;
  /** Called with the new sizes (%) after every resize, collapse or restore. */
  onLayout?: (sizes: number[]) => void;
}

interface GroupState {
  signature: string;
  sizes: number[];
  restore: Record<string, number>;
}

/**
 * Container of resizable panels. Children must be ResizablePanel and ResizeHandle elements
 * (direct children, alternating). Sizes are percentages of the group.
 */
export function ResizablePanelGroup({
  direction = 'horizontal',
  autoSaveId,
  onLayout,
  className,
  children,
  ...props
}: ResizablePanelGroupProps) {
  const baseId = useId();
  const items = Children.toArray(children);
  const panels: PanelConstraints[] = [];
  const slots: number[] = [];
  for (const child of items) {
    if (isValidElement(child) && child.type === ResizablePanel) {
      const p = (child as ReactElement<ResizablePanelProps>).props;
      const minSize = p.minSize ?? 0;
      panels.push({
        id: p.id ?? `${baseId}-panel-${panels.length}`,
        defaultSize: p.defaultSize,
        minSize,
        maxSize: p.maxSize ?? 100,
        collapsible: p.collapsible ?? false,
        collapsedSize: Math.min(p.collapsedSize ?? 0, minSize),
      });
    }
    slots.push(panels.length - 1);
  }
  const signature = panels.map((p) => `${p.id}:${p.minSize}:${p.maxSize}`).join('|');
  const initial = (): GroupState => ({
    signature,
    sizes: loadSizes(autoSaveId, panels.length) ?? defaultSizes(panels),
    restore: {},
  });
  const [state, setState] = useState<GroupState>(initial);
  // Panels added / removed / re-constrained: fall back to the (persisted or) default layout.
  const current = state.signature === signature ? state : initial();

  const update: GroupContextValue['update'] = (sizes, options) => {
    setState({ signature, sizes, restore: options?.restore ?? current.restore });
    onLayout?.(sizes);
    if (options?.persist) saveSizes(autoSaveId, sizes);
  };

  const ctx: GroupContextValue = { direction, panels, sizes: current.sizes, restore: current.restore, update };
  const s = resizableVariants({ direction });
  return (
    <GroupContext.Provider value={ctx}>
      <div data-resizable-group="" data-direction={direction} className={cn(s.group(), className)} {...props}>
        {items.map((child, i) => {
          const key = isValidElement(child) && child.key != null ? child.key : i;
          return (
            <SlotContext.Provider key={key} value={slots[i] ?? -1}>
              {child}
            </SlotContext.Provider>
          );
        })}
      </div>
    </GroupContext.Provider>
  );
}

export interface ResizablePanelProps extends DivProps {
  /** Stable id (also referenced by the handle's aria-controls). */
  id?: string;
  /** Initial size in % (panels without one share the remainder). */
  defaultSize?: number;
  /** Minimum size in %. */
  minSize?: number;
  /** Maximum size in %. */
  maxSize?: number;
  /** Can shrink to `collapsedSize` (drag past half its minimum, or Enter on the handle). */
  collapsible?: boolean;
  /** Size in % when collapsed. Default 0 (the content becomes inert). */
  collapsedSize?: number;
}

const PANEL_CONFIG_KEYS = ['id', 'defaultSize', 'minSize', 'maxSize', 'collapsible', 'collapsedSize'] as const;

/** Strips the layout config (read by the group) from the props spread onto the panel element. */
function domProps(props: Omit<ResizablePanelProps, 'className' | 'style'>): DivProps {
  const out: Partial<ResizablePanelProps> = { ...props };
  for (const key of PANEL_CONFIG_KEYS) delete out[key];
  return out;
}

/** One pane of a ResizablePanelGroup. */
export function ResizablePanel({ className, style, ...config }: ResizablePanelProps) {
  const props = domProps(config);
  const ctx = useGroup('ResizablePanel');
  const index = useContext(SlotContext);
  const panel = ctx.panels[index];
  const size = ctx.sizes[index] ?? 0;
  const collapsed = panel ? isCollapsed(size, panel) : false;
  return (
    <div
      id={panel?.id}
      data-resizable-panel=""
      data-collapsed={collapsed ? '' : undefined}
      data-size={Math.round(size)}
      inert={collapsed && size <= 0.01 ? true : undefined}
      className={cn(resizableVariants().panel(), className)}
      style={{ flexGrow: size, flexShrink: 1, flexBasis: 0, overflow: 'hidden', ...style }}
      {...props}
    />
  );
}

export interface ResizeHandleProps extends DivProps {
  /** Shows a small grip on the line. */
  withHandle?: boolean;
  /** Arrow-key step in %. Default 5. */
  step?: number;
  /** Not draggable nor focusable. */
  disabled?: boolean;
}

const isRtl = (el: Element) => getComputedStyle(el).direction === 'rtl';

interface DragState {
  start: number;
  /** -1 when a horizontal group runs right to left (the first panel is on the right). */
  sign: number;
  px: number;
  sizes: number[];
  last: number[];
}

/**
 * The draggable divider between two panels: role="separator" with aria-valuenow (size of the panel
 * before it). Pointer drag; arrows resize by `step`; Home / End jump to min / max; Enter collapses
 * or restores the adjacent collapsible panel.
 */
export function ResizeHandle({
  withHandle,
  step = 5,
  disabled,
  className,
  onKeyDown,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  'aria-label': ariaLabelProp,
  ...props
}: ResizeHandleProps) {
  const { t } = useI18n();
  const ariaLabel = ariaLabelProp ?? t('common.resize');
  const ctx = useGroup('ResizeHandle');
  const i = useContext(SlotContext);
  const dragRef = useRef<DragState | null>(null);
  const [dragging, setDragging] = useState(false);
  const { direction, panels, sizes, restore, update } = ctx;
  const a = panels[i];
  const b = panels[i + 1];
  const sizeA = sizes[i] ?? 0;
  const horizontal = direction === 'horizontal';
  const s = resizableVariants({ direction });

  function toggleCollapse() {
    if (!a || !b) return;
    const sizeB = sizes[i + 1] ?? 0;
    const total = sizeA + sizeB;
    const target = a.collapsible ? a : b.collapsible ? b : null;
    if (!target) return;
    const current = target === a ? sizeA : sizeB;
    let nextTarget: number;
    let nextRestore = restore;
    if (isCollapsed(current, target)) {
      const remembered = restore[target.id] ?? target.defaultSize ?? target.minSize;
      const other = target === a ? b : a;
      nextTarget = clamp(remembered, target.minSize, Math.min(target.maxSize, total - other.minSize));
    } else {
      nextTarget = target.collapsedSize;
      nextRestore = { ...restore, [target.id]: current };
    }
    const nextA = target === a ? nextTarget : total - nextTarget;
    update(setPair(sizes, i, nextA), { persist: true, restore: nextRestore });
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    onKeyDown?.(event);
    if (event.defaultPrevented || disabled || !a || !b) return;
    const rtl = horizontal && isRtl(event.currentTarget);
    const dec = horizontal ? (rtl ? 'ArrowRight' : 'ArrowLeft') : 'ArrowUp';
    const inc = horizontal ? (rtl ? 'ArrowLeft' : 'ArrowRight') : 'ArrowDown';
    let next: number[] | null = null;
    if (event.key === dec) next = movePair(sizes, panels, i, sizeA - step);
    else if (event.key === inc) next = movePair(sizes, panels, i, sizeA + step);
    else if (event.key === 'Home') next = movePair(sizes, panels, i, a.minSize);
    else if (event.key === 'End') next = movePair(sizes, panels, i, a.maxSize);
    else if (event.key === 'Enter') {
      event.preventDefault();
      toggleCollapse();
      return;
    }
    if (!next) return;
    event.preventDefault();
    update(next, { persist: true });
  }

  function handlePointerDown(event: PointerEvent<HTMLDivElement>) {
    onPointerDown?.(event);
    if (event.defaultPrevented || disabled || event.button !== 0) return;
    const handle = event.currentTarget;
    const group = handle.parentElement;
    if (!group) return;
    event.preventDefault();
    handle.focus();
    try {
      handle.setPointerCapture(event.pointerId);
    } catch {}
    let px = 0;
    group.querySelectorAll<HTMLElement>(':scope > [data-resizable-panel]').forEach((el) => {
      const rect = el.getBoundingClientRect();
      px += horizontal ? rect.width : rect.height;
    });
    const sign = horizontal && isRtl(handle) ? -1 : 1;
    dragRef.current = { start: horizontal ? event.clientX : event.clientY, sign, px, sizes, last: sizes };
    setDragging(true);
  }

  function handlePointerMove(event: PointerEvent<HTMLDivElement>) {
    onPointerMove?.(event);
    const drag = dragRef.current;
    if (!drag || drag.px <= 0) return;
    const delta = (((horizontal ? event.clientX : event.clientY) - drag.start) / drag.px) * 100 * drag.sign;
    const next = movePair(drag.sizes, panels, i, (drag.sizes[i] ?? 0) + delta);
    drag.last = next;
    update(next);
  }

  function endDrag(event: PointerEvent<HTMLDivElement>) {
    const drag = dragRef.current;
    if (!drag) return;
    dragRef.current = null;
    setDragging(false);
    try {
      event.currentTarget.releasePointerCapture(event.pointerId);
    } catch {}
    if (drag.last !== drag.sizes) update(drag.last, { persist: true });
  }

  const min = a ? (a.collapsible ? a.collapsedSize : a.minSize) : 0;
  const max = a && b ? Math.min(a.maxSize, sizeA + (sizes[i + 1] ?? 0) - (b.collapsible ? b.collapsedSize : b.minSize)) : 100;
  const Grip = horizontal ? GripVertical : GripHorizontal;
  return (
    <div
      role="separator"
      tabIndex={disabled ? undefined : 0}
      aria-label={ariaLabel}
      aria-orientation={horizontal ? 'vertical' : 'horizontal'}
      aria-controls={a?.id}
      aria-valuenow={Math.round(sizeA)}
      aria-valuemin={Math.round(min)}
      aria-valuemax={Math.round(max)}
      aria-disabled={disabled || undefined}
      data-resize-handle=""
      data-dragging={dragging ? '' : undefined}
      data-disabled={disabled ? '' : undefined}
      className={cn(s.handle(), className)}
      onKeyDown={handleKeyDown}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={(e) => {
        onPointerUp?.(e);
        endDrag(e);
      }}
      onPointerCancel={(e) => {
        onPointerCancel?.(e);
        endDrag(e);
      }}
      {...props}
    >
      {withHandle && (
        <span className={s.grip()} aria-hidden>
          <Grip size={10} />
        </span>
      )}
    </div>
  );
}

export {
  ResizablePanelGroup,
  ResizablePanel,
  ResizeHandle,
  type ResizablePanelGroupProps,
  type ResizablePanelProps,
  type ResizeHandleProps,
} from './Resizable';
export { resizableVariants, type ResizableVariantProps } from './resizable.variants';
export { doc as resizableDoc } from './Resizable.doc';

/** Pure layout math and persistence for ResizablePanelGroup (sizes are % of the group). */

export interface PanelConstraints {
  id: string;
  defaultSize?: number;
  minSize: number;
  maxSize: number;
  collapsible: boolean;
  collapsedSize: number;
}

const EPSILON = 0.01;

export const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

export function isCollapsed(size: number, panel: PanelConstraints) {
  return panel.collapsible && size <= panel.collapsedSize + EPSILON;
}

/** Default sizes: explicit `defaultSize`s first, the remainder shared by the panels without one. */
export function defaultSizes(panels: PanelConstraints[]): number[] {
  const fixed = panels.reduce((sum, p) => sum + (p.defaultSize ?? 0), 0);
  const free = panels.filter((p) => p.defaultSize == null).length;
  const share = free ? Math.max(0, 100 - fixed) / free : 0;
  const raw = panels.map((p) => clamp(p.defaultSize ?? share, p.minSize, p.maxSize));
  const sum = raw.reduce((a, b) => a + b, 0);
  return sum > 0 ? raw.map((s) => (s / sum) * 100) : raw;
}

/**
 * New size for panel A of the adjacent pair (A, B) when the handle between them is dragged
 * towards `target`. B absorbs the difference; min / max of both are respected, and a collapsible
 * panel snaps shut once dragged past half of its minimum.
 */
export function resolvePair(target: number, a: PanelConstraints, b: PanelConstraints, total: number): number {
  if (a.collapsible && target <= (a.collapsedSize + a.minSize) / 2 && total - a.collapsedSize <= b.maxSize) {
    return a.collapsedSize;
  }
  if (b.collapsible && total - target <= (b.collapsedSize + b.minSize) / 2 && total - b.collapsedSize <= a.maxSize) {
    return total - b.collapsedSize;
  }
  const lo = Math.max(a.minSize, total - b.maxSize);
  const hi = Math.min(a.maxSize, total - b.minSize);
  return lo <= hi ? clamp(target, lo, hi) : clamp(target, hi, lo);
}

/** Returns a copy of `sizes` with panel `i` set to `nextA` and panel `i + 1` taking the rest of the pair. */
export function setPair(sizes: number[], i: number, nextA: number): number[] {
  const a = sizes[i];
  const b = sizes[i + 1];
  if (a == null || b == null) return sizes;
  const next = sizes.slice();
  next[i] = nextA;
  next[i + 1] = a + b - nextA;
  return next;
}

/** Moves the handle after panel `i` so that panel `i` aims for `target` (%). */
export function movePair(sizes: number[], panels: PanelConstraints[], i: number, target: number): number[] {
  const a = panels[i];
  const b = panels[i + 1];
  const sa = sizes[i];
  const sb = sizes[i + 1];
  if (!a || !b || sa == null || sb == null) return sizes;
  return setPair(sizes, i, resolvePair(target, a, b, sa + sb));
}

const storageKey = (id: string) => `gntik-ui:resizable:${id}`;

/** Reads persisted sizes; returns null when missing, malformed or not matching the panel count. */
export function loadSizes(autoSaveId: string | undefined, count: number): number[] | null {
  if (!autoSaveId) return null;
  try {
    const raw = localStorage.getItem(storageKey(autoSaveId));
    if (!raw) return null;
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed) || parsed.length !== count) return null;
    if (!parsed.every((n): n is number => typeof n === 'number' && Number.isFinite(n) && n >= 0)) return null;
    const sum = parsed.reduce((a, b) => a + b, 0);
    return Math.abs(sum - 100) < 1 ? parsed : null;
  } catch {
    return null;
  }
}

export function saveSizes(autoSaveId: string | undefined, sizes: number[]) {
  if (!autoSaveId) return;
  try {
    localStorage.setItem(storageKey(autoSaveId), JSON.stringify(sizes.map((s) => Math.round(s * 100) / 100)));
  } catch {}
}

import { tv, type VariantProps } from '../../utils/tv';

export const resizableVariants = tv({
  slots: {
    group: 'flex size-full min-h-0 min-w-0 overflow-hidden',
    panel: 'min-h-0 min-w-0',
    handle: [
      'relative z-10 flex shrink-0 touch-none items-center justify-center bg-border select-none',
      'transition-colors duration-150 motion-reduce:transition-none',
      'hover:bg-primary/60 data-dragging:bg-primary focus-visible:bg-primary',
      'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
      "after:absolute after:content-['']",
      'data-disabled:pointer-events-none data-disabled:bg-border',
    ],
    grip: 'flex items-center justify-center rounded-sm border border-border bg-card text-muted-foreground shadow-sm',
  },
  variants: {
    direction: {
      horizontal: {
        group: 'flex-row',
        handle: 'w-px cursor-col-resize after:inset-y-0 after:-inset-x-1.5',
        grip: 'h-6 w-3.5',
      },
      vertical: {
        group: 'flex-col',
        handle: 'h-px cursor-row-resize after:inset-x-0 after:-inset-y-1.5',
        grip: 'h-3.5 w-6',
      },
    },
  },
  defaultVariants: { direction: 'horizontal' },
});

export type ResizableVariantProps = VariantProps<typeof resizableVariants>;

import { DirectionProvider } from '@base-ui/react/direction-provider';
import { createContext, useContext, useEffect, useMemo, type ReactNode } from 'react';
import { createFormatters, localeDirection, type I18nFormatters } from './format';
import { catalogs } from './messages';
import { en, type Messages } from './messages/en';

export type Direction = 'ltr' | 'rtl';

/** What useI18n() returns: the translator, Intl formatters, the locale and the text direction. */
export interface I18n extends I18nFormatters {
  locale: string;
  dir: Direction;
}

export interface I18nProviderProps {
  /** BCP 47 locale ("es", "es-MX", "ar"). Picks the built-in catalog by language; unknown → English. */
  locale: string;
  /** Overrides or additions on top of the built-in catalog (e.g. a full catalog for another language). */
  messages?: Partial<Messages>;
  /** Text direction; defaults to the locale's (rtl for Arabic, Hebrew, Persian, Urdu…). */
  dir?: Direction;
  /**
   * Where `dir` and `lang` are applied: `wrapper` (default) renders a `display: contents` div;
   * `document` sets them on `<html>` (also covers portalled overlays); `none` leaves it to you.
   */
  applyTo?: 'wrapper' | 'document' | 'none';
  children?: ReactNode;
}

const I18nContext = createContext<I18n | null>(null);
const DEFAULT_I18N: I18n = { locale: 'en', dir: 'ltr', ...createFormatters('en', en) };

/** The built-in catalog for a locale's language, falling back to English. */
export function builtInMessages(locale: string): Messages {
  const lang = locale.split(/[-_]/)[0]?.toLowerCase() ?? '';
  return (catalogs as Record<string, Messages | undefined>)[lang] ?? en;
}

/**
 * Locale, messages and direction for every kit component below it. Also sets Base UI's
 * direction, so arrow-key navigation (Tabs, Menu, Slider, Toolbar…) follows RTL.
 */
export function I18nProvider({ locale, messages, dir, applyTo = 'wrapper', children }: I18nProviderProps) {
  const direction = dir ?? localeDirection(locale);
  const value = useMemo<I18n>(() => {
    const merged: Messages = { ...builtInMessages(locale), ...messages };
    return { locale, dir: direction, ...createFormatters(locale, merged) };
  }, [locale, messages, direction]);

  useEffect(() => {
    if (applyTo !== 'document') return;
    const html = document.documentElement;
    const prev = { dir: html.getAttribute('dir'), lang: html.getAttribute('lang') };
    html.setAttribute('dir', direction);
    html.setAttribute('lang', locale);
    return () => {
      if (prev.dir === null) html.removeAttribute('dir');
      else html.setAttribute('dir', prev.dir);
      if (prev.lang === null) html.removeAttribute('lang');
      else html.setAttribute('lang', prev.lang);
    };
  }, [applyTo, direction, locale]);

  const content = <DirectionProvider direction={direction}>{children}</DirectionProvider>;
  return (
    <I18nContext.Provider value={value}>
      {applyTo === 'wrapper' ? (
        <div dir={direction} lang={locale} className="contents">
          {content}
        </div>
      ) : (
        content
      )}
    </I18nContext.Provider>
  );
}

/** Translator, Intl formatters, locale and direction. Outside an I18nProvider: English, LTR. */
export function useI18n(): I18n {
  return useContext(I18nContext) ?? DEFAULT_I18N;
}

/** The provider's value, or null outside one (lets components keep runtime-locale defaults). */
export function useOptionalI18n(): I18n | null {
  return useContext(I18nContext);
}

/**
 * `dir` for portalled overlays: rendered outside the provider's wrapper, they carry the
 * direction themselves. Undefined outside a provider, so the document's direction applies.
 */
export function usePortalDir(): Direction | undefined {
  return useContext(I18nContext)?.dir;
}

import type { MessageKey, Messages } from './messages/en';

/** Values interpolated into a message: `{name}` placeholders and plural selectors. */
export type MessageVars = Record<string, string | number>;

/** Scripts written right to left (language subtag). */
const RTL_LANGUAGES = new Set(['ar', 'arc', 'ckb', 'dv', 'fa', 'he', 'iw', 'ks', 'ku', 'ps', 'sd', 'ug', 'ur', 'yi']);

/** `rtl` for Arabic, Hebrew, Persian, Urdu… (by language subtag or Intl text info), else `ltr`. */
export function localeDirection(locale: string): 'ltr' | 'rtl' {
  try {
    const loc = new Intl.Locale(locale) as Intl.Locale & {
      getTextInfo?: () => { direction?: string };
      textInfo?: { direction?: string };
    };
    const info = loc.getTextInfo?.() ?? loc.textInfo;
    if (info?.direction === 'rtl' || info?.direction === 'ltr') return info.direction;
    return RTL_LANGUAGES.has(loc.language) ? 'rtl' : 'ltr';
  } catch {
    return RTL_LANGUAGES.has(locale.split(/[-_]/)[0]?.toLowerCase() ?? '') ? 'rtl' : 'ltr';
  }
}

/** Index of the brace closing the one at `open` (nested braces allowed). */
function matchBrace(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}' && --depth === 0) return i;
  }
  return -1;
}

/** `one {# item} other {# items}` → `{ one: '# item', other: '# items' }`. */
function parseBranches(body: string): Record<string, string> {
  const branches: Record<string, string> = {};
  let i = 0;
  while (i < body.length) {
    const open = body.indexOf('{', i);
    if (open < 0) break;
    const name = body.slice(i, open).trim();
    const close = matchBrace(body, open);
    if (close < 0) break;
    branches[name] = body.slice(open + 1, close);
    i = close + 1;
  }
  return branches;
}

/** Fills `{name}` placeholders and `{count, plural, one {…} other {…}}` selectors. */
export function interpolate(template: string, vars: MessageVars | undefined, locale: string): string {
  if (!vars || !template.includes('{')) return template;
  let out = '';
  let i = 0;
  while (i < template.length) {
    const open = template.indexOf('{', i);
    if (open < 0) {
      out += template.slice(i);
      break;
    }
    out += template.slice(i, open);
    const close = matchBrace(template, open);
    if (close < 0) {
      out += template.slice(open);
      break;
    }
    const inner = template.slice(open + 1, close);
    const plural = /^\s*(\w+)\s*,\s*plural\s*,(.*)$/s.exec(inner);
    if (plural) {
      const name = plural[1] ?? '';
      const n = Number(vars[name] ?? 0);
      const branches = parseBranches(plural[2] ?? '');
      const rule = new Intl.PluralRules(locale).select(n);
      const branch = branches[`=${n}`] ?? branches[rule] ?? branches.other ?? '';
      out += interpolate(branch.replaceAll('#', new Intl.NumberFormat(locale).format(n)), vars, locale);
    } else {
      const value = vars[inner.trim()];
      out += value === undefined ? `{${inner}}` : String(value);
    }
    i = close + 1;
  }
  return out;
}

export type DateValue = Date | number | string;
const toDate = (value: DateValue) => (value instanceof Date ? value : new Date(value));

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ['year', 365 * 24 * 3600],
  ['month', 30 * 24 * 3600],
  ['week', 7 * 24 * 3600],
  ['day', 24 * 3600],
  ['hour', 3600],
  ['minute', 60],
  ['second', 1],
];

/** The translator and Intl formatters for one locale. */
export interface I18nFormatters {
  /** Translates a built-in key, filling placeholders. */
  t: (key: MessageKey, vars?: MessageVars) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatCurrency: (value: number, currency: string, options?: Intl.NumberFormatOptions) => string;
  formatDate: (value: DateValue, options?: Intl.DateTimeFormatOptions) => string;
  /**
   * Relative time. With a unit, formats `value` in it ("in 3 days"); with a date, picks the
   * largest fitting unit against `now` ("5 minutes ago").
   */
  formatRelativeTime: {
    (value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
    (value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  };
  formatList: (items: readonly string[], options?: Intl.ListFormatOptions) => string;
}

export function createFormatters(locale: string, messages: Messages): I18nFormatters {
  function formatRelativeTime(value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(
    value: number | Date,
    unitOrNow?: Intl.RelativeTimeFormatUnit | Date | number,
    options: Intl.RelativeTimeFormatOptions = { numeric: 'auto' },
  ): string {
    const rtf = new Intl.RelativeTimeFormat(locale, options);
    if (typeof value === 'number' && typeof unitOrNow === 'string') return rtf.format(value, unitOrNow);
    const now = unitOrNow instanceof Date ? unitOrNow.getTime() : typeof unitOrNow === 'number' ? unitOrNow : Date.now();
    const seconds = Math.round((toDate(value).getTime() - now) / 1000);
    const [unit, size] = RELATIVE_UNITS.find(([, s]) => Math.abs(seconds) >= s) ?? ['second', 1];
    return rtf.format(Math.round(seconds / size), unit);
  }
  return {
    t: (key, vars) => interpolate(messages[key] ?? key, vars, locale),
    formatNumber: (value, options) => new Intl.NumberFormat(locale, options).format(value),
    formatCurrency: (value, currency, options) => new Intl.NumberFormat(locale, { style: 'currency', currency, ...options }).format(value),
    formatDate: (value, options = { dateStyle: 'medium' }) => new Intl.DateTimeFormat(locale, options).format(toDate(value)),
    formatRelativeTime,
    formatList: (items, options = { style: 'long', type: 'conjunction' }) => new Intl.ListFormat(locale, options).format(items),
  };
}

